/// The tag of `c` in a sorted range table, if covered.
pub(crate) fn lookup<T: Copy>(t: &[(u32, u32, T)], c: char) -> Option<T> {
    let c = c as u32;
    let i = t.partition_point(|r| r.1 < c);
    t.get(i).filter(|r| r.0 <= c).map(|r| r.2)
}

/// Whether `c` is in a sorted range table.
pub(crate) fn contains(t: &[(u32, u32)], c: char) -> bool {
    let c = c as u32;
    let i = t.partition_point(|r| r.1 < c);
    t.get(i).is_some_and(|r| r.0 <= c)
}
